for fp,(h,paras) in EXTRA.items():
 p=Path(fp); s=p.read_text(encoding='utf-8')
 if FAV not in s:
  s=s.replace('<head>','<head>'+FAV,1)
 if 'data-phase2-extra="1"' not in s:
  block='<section class="ptf-box" data-phase2-extra="1"><h2>'+escape(h)+'</h2>'+''.join('<p>'+escape(x)+'</p>' for x in paras)+'</section>'
  idx=s.find('<div class="ptf-cta">')
  if idx!=-1: s=s[:idx]+block+s[idx:]
 p.write_text(s,encoding='utf-8')
 print('extended phase2',fp)
